"""Auto-generated master-data codes - backfill missing codes.

Branch, department, designation and shift codes are now generated by the server
(`BR-001`, `DEPT-001`, `DSG-001`, `SHF-001`). Rows that were saved without a code get one here,
numbered after the highest existing generated code in the same company. Codes that already
exist are left untouched. Downgrade is a no-op (the codes are harmless data).

Revision ID: 20261108090000
Revises: 20261107090000
"""

from alembic import op

revision = "20261108090000"
down_revision = "20261107090000"
branch_labels = None
depends_on = None

_TARGETS = (("branch", "BR"), ("department", "DEPT"), ("designation", "DSG"), ("shift", "SHF"))


def upgrade() -> None:
    for table, prefix in _TARGETS:
        op.execute(
            f"""
            WITH base AS (
              SELECT company_id,
                     COALESCE(MAX(substring(code FROM '^{prefix}-(\\d+)$')::int), 0) AS highest
              FROM {table} GROUP BY company_id
            ), numbered AS (
              SELECT t.id,
                     b.highest + row_number() OVER (
                       PARTITION BY t.company_id ORDER BY t.created_at, t.id
                     ) AS n
              FROM {table} t JOIN base b ON b.company_id = t.company_id
              WHERE t.code IS NULL OR btrim(t.code) = ''
            )
            UPDATE {table} t SET code = '{prefix}-' || lpad(numbered.n::text, 3, '0')
            FROM numbered WHERE t.id = numbered.id
            """
        )


def downgrade() -> None:
    pass
